local config = {
  ui_story_5054_50540101_1_dialog_content = "<color=#a8886f>Kelopaknya terbakar menjadi abu sebelum menyentuh tanah, pengingat akan kerusuhan yang baru saja dialami taman yang tenang ini.</color>",
  ui_story_5054_50540101_2_dialog_content = "<color=#a8886f>Jalan setapaknya, masih dilapisi dengan bunga yang tumbuh di kedua sisinya, memotong pintu labirin dan mengarah ke aula dengan kubah yang sangat tinggi.</color>",
  ui_story_5054_50540101_3_dialog_content = "<color=#a8886f>Seorang pelayan meletakkan makanan ringan di sebuah ruangan, lalu berbalik dan pergi. Tak lama setelah itu, terdengar obrolan di luar pintu...</color>",
  ui_story_5054_50540101_4_option_content = "(Menguping)",
  ui_story_5054_50540101_5_dialog_content = "Jadi, apakah benar Putri Veronica ada di sana?",
  ui_story_5054_50540101_6_dialog_content = "Memang benar, saya melihatnya dengan mata kepala sendiri.",
  ui_story_5054_50540101_7_dialog_content = "Orang-orang itu terlihat mencurigakan. Mengapa Yang Mulia bersama mereka?",
  ui_story_5054_50540101_8_dialog_content = "Tenang, Ms. Rot sedang bersama Lady Joshua. Itu bukan urusan kami.",
  ui_story_5054_50540101_9_dialog_content = "Tapi itu aneh. Bukankah Ms. Rot favorit Tuan Kota? Kenapa dia tidak ada di perayaan itu?",
  ui_story_5054_50540101_10_dialog_content = "Apakah kamu tidak tahu? Wanita Joshua dan Ms. Rot sangat ketat, dan Tuan Kota yang menyuruh Ms. Rot untuk menjaga Nyonya.",
  ui_story_5054_50540101_11_dialog_content = "Tapi jika mereka begitu ketat, mengapa Lady Joshua sengaja mengirim Ms. Rot pergi?",
  ui_story_5054_50540101_12_dialog_content = "Mustahil! Saya mendengar Ms. Rot bukan hanya kerabat jauh Lady Joshua, tapi murid terakhirnya juga!",
  ui_story_5054_50540101_13_option_content = "Saudara jauh...?",
  ui_story_5054_50540101_14_dialog_content = "Ya, tapi mungkin tidak ada hubungan darah lagi.",
  ui_story_5054_50540101_15_option_content = "Murid terakhir...?",
  ui_story_5054_50540101_16_dialog_content = "Ya. Nona Rot seharusnya adalah anak ajaib tetapi tidak memiliki bimbingan.",
  ui_story_5054_50540101_17_dialog_content = "Orang tuanya mencari Sir Caleb melalui koneksi dan kebetulan bertemu dengan Lady Joshua.",
  ui_story_5054_50540101_18_dialog_content = "Wanita Joshua dan Ms. Rot langsung cocok, jadi dia membimbingnya selama bertahun-tahun.",
  ui_story_5054_50540101_19_dialog_content = "Hei, siapa yang bertanya?",
  ui_story_5054_50540101_20_dialog_content = "Bukankah itu kamu?",
  ui_story_5054_50540101_21_dialog_content = "Ehem, ssst—",
  ui_story_5054_50540101_22_dialog_content = "Tembok punya telinga... Kita akan ambil ini nanti.",
  ui_story_5054_50540102_1_dialog_content = "<color=#a8886f>Angin sepoi-sepoi yang bertiup dengan cepat mematahkan daun dan kelopak yang segar dan lezat.</color>",
  ui_story_5054_50540102_2_dialog_content = "<color=#a8886f>Kegentingan!</color>",
  ui_story_5054_50540102_3_dialog_content = "<color=#a8886f>Sebuah surat dengan tepi yang terbakar mengeluarkan suara kering yang menusuk telinga saat diinjak.</color>",
  ui_story_5054_50540102_4_dialog_content = "Apa ini?",
  ui_story_5054_50540102_5_dialog_content = "Apa kau menemukan sesuatu, Caleb?",
  ui_story_5054_50540102_6_dialog_content = "Tumpukan surat yang terbakar, tampaknya milik kakakku...",
  ui_story_5054_50540102_7_option_content = "(Mengambil satu)",
  ui_story_5054_50540102_8_dialog_content = "<color=#a8886f>Beberapa baris tulisan elegan samar-samar terlihat di atas lembaran yang hangus.</color>",
  ui_story_5054_50540102_9_dialog_content = "\"Putra Montague ...\"",
  ui_story_5054_50540102_10_dialog_content = "Aku tahu tulisan tangan dan tanda tangannya... Ayahku yang menulis ini?!",
  ui_story_5054_50540102_11_dialog_content = "\"Pada akhirnya, aku tidak lebih dari kutu buku pengecut.\"",
  ui_story_5054_50540102_12_dialog_content = "\"Satu-satunya hal yang bisa kulakukan adalah pergi dengan...\"",
  ui_story_5054_50540102_13_dialog_content = "\"Aku harap kamu dan anak itu akan hidup bahagia selamanya.\"",
  ui_story_5054_50540102_14_dialog_content = "Siapa anak Montague?",
  ui_story_5054_50540102_15_dialog_content = "Entahlah.",
  ui_story_5054_50540102_16_dialog_content = "Ayah saya adalah seorang sarjana yang welas asih. Saya tidak akan terkejut jika dia mensponsori anak orang lain.",
  ui_story_5054_50540102_17_dialog_content = "Ehem.",
  ui_story_5054_50540102_18_dialog_content = "<color=#a8886f>Schwartz mengeluarkan batuk yang lemah, tetapi urgensi datang dengan keras dan jelas.</color>",
  ui_story_5054_50540102_19_dialog_content = "Jangan khawatir tentang itu dan pergi saja!",
  ui_story_5054_50540103_1_dialog_content = "<color=#a8886f>Suara mendesing!</color>",
  ui_story_5054_50540103_2_dialog_content = "<color=#a8886f>Seorang gadis muda berambut merah muncul tiba-tiba dan menghentikan seorang kesatria muda yang bergegas menuju alun-alun.</color>",
  ui_story_5054_50540103_3_dialog_content = "(Saya melihat dua sosok menghalangi jalan di depan...)",
  ui_story_5054_50540103_4_dialog_content = "Sharona?",
  ui_story_5054_50540103_5_dialog_content = "Maaf, apa aku mengenalmu?",
  ui_story_5054_50540103_6_dialog_content = "Lihatlah dirimu dengan pakaian kesatria konyol itu! Saya berharap saya tidak mengenali Anda, tetapi tanduk di kepala Anda membuatnya sulit untuk tidak mengenali Anda.",
  ui_story_5054_50540103_7_dialog_content = "Siapa kau?",
  ui_story_5054_50540103_8_dialog_content = "Anda benar-benar tidak tahu?",
  ui_story_5054_50540103_9_dialog_content = "Saya belum memeriksa daftar buronan terbaru.",
  ui_story_5054_50540103_10_dialog_content = "<color=#a8886f>Api tiba-tiba bermanifestasi di belakang gadis itu tapi kemudian menyebar seperti nafas yang dihembuskan.</color>",
  ui_story_5054_50540103_11_dialog_content = "Baiklah, izinkan saya menceritakan sebuah kisah.",
  ui_story_5054_50540103_12_dialog_content = "Seorang ibu dengan Dragonkin terbangun telah melahirkan dua anak perempuan. Warisannya membuatnya kehilangan kendali dan dia dibunuh oleh keluarganya.",
  ui_story_5054_50540103_13_dialog_content = "Untuk melindungi naganya yang akan menetas, sang putri sulung memilih merantau hingga menetap di Umbraton. Putri bungsu tumbuh tanpa mengetahui ibunya dibunuh oleh sukunya.",
  ui_story_5054_50540103_14_dialog_content = "Maaf, saya belum pernah mendengar cerita itu sebelumnya, tapi saya merasa Anda adalah putri sulung itu.",
  ui_story_5054_50540103_15_dialog_content = "Apa yang kamu lakukan di Lumopolis? Apakah Anda bertanggung jawab atas apa yang terjadi di alun-alun?",
  ui_story_5054_50540103_16_dialog_content = "Saya melihat mereka tidak memberi tahu Anda apa pun. Nah, jangan ragu untuk tetap berperan sebagai boneka Lumopolis.",
  ui_story_5054_50540103_17_dialog_content = "<color=#a8886f>Gadis berambut merah yang sedih itu berbalik, tapi Sharona membidiknya tanpa niat membiarkannya pergi.</color>",
  ui_story_5054_50540103_18_option_content = "Datang melalui!",
  ui_story_5054_50540103_19_option_content = "Pembunuh ada di sini sekarang!",
  ui_story_5054_50540103_20_dialog_content = "Apa?",
  ui_story_5054_50540103_21_dialog_content = "<color=#a8886f>Gadis berambut merah menghilang dalam sekejap mata, saat kalian semua berlari melewati yang bingung Sharona.</color>",
  ui_story_5054_50540201_1_dialog_content = "<color=#a8886f>Pita warna-warni, spanduk, dan dekorasi khusus membuat kota putih bersih ini tampak jauh berbeda dari biasanya. Anda bersembunyi di balik spanduk besar dan menghindari pengejar Anda.</color>",
  ui_story_5054_50540201_2_dialog_content = "<color=#a8886f>Tepat ketika Anda memutuskan apakah akan keluar, beberapa sosok berhenti di depan spanduk ...</color>",
  ui_story_5054_50540201_3_dialog_content = "Anda tidak membawa Nona Roshee bersamamu hari ini, Duke Troy?",
  ui_story_5054_50540201_4_dialog_content = "(Roshee? Bukankah itu nama masa kecil Michael?)",
  ui_story_5054_50540201_5_dialog_content = "Saya menginstruksikannya untuk tinggal di rumah dan belajar. Dia dapat mengambil bagian dalam acara seperti itu ketika dia lebih tua.",
  ui_story_5054_50540201_6_dialog_content = "Keponakan Anda yang berkeliaran di jalan, menangkap pencuri, dan pembasmi kejahatan itu bersedia tinggal di rumah dan belajar?",
  ui_story_5054_50540201_7_dialog_content = "Saya harus belajar teknik mendisiplinkan anak dari Anda suatu hari nanti, Duke Troy.",
  ui_story_5054_50540201_8_dialog_content = "Tidak ada yang istimewa. Meskipun Roshee bukan milikku, dia adalah putri kakakku, dengan darah Troy mengalir di nadinya.",
  ui_story_5054_50540201_9_dialog_content = "Anak-anak akan tahu apa yang harus dilakukan ketika saatnya tiba.",
  ui_story_5054_50540201_10_dialog_content = "Pak…",
  ui_story_5054_50540201_11_dialog_content = "Mengapa Anda terlihat begitu stres?",
  ui_story_5054_50540201_12_dialog_content = "Nona Roshee kabur!",
  ui_story_5054_50540201_13_dialog_content = "Aku akan membiarkanmu pergi, Duke Troy. Sampai jumpa di mimbar.",
  ui_story_5054_50540201_14_dialog_content = "Kami akan, Duke Hermes.",
  ui_story_5054_50540201_15_dialog_content = "<color=#a8886f>Setelah Lachon pergi, Otto menjadi murung.</color>",
  ui_story_5054_50540201_16_dialog_content = "Bagaimana Anda bisa mengungkitnya di depan orang lain, Anda ampas!",
  ui_story_5054_50540201_17_dialog_content = "Maaf, Pak, saya sedang terburu-buru... Ini tidak akan terjadi lagi!",
  ui_story_5054_50540201_18_dialog_content = "Tidak akan ada waktu berikutnya!",
  ui_story_5054_50540201_19_dialog_content = "Apakah Roshee menyebutkan ke mana dia pergi?",
  ui_story_5054_50540201_20_dialog_content = "Tidak... Tapi pelayan itu mengatakan dia mendapat catatan melalui jendela sebelum dia pergi.",
  ui_story_5054_50540201_21_dialog_content = "<color=#a8886f>Otto mengikuti pelayan itu pulang, tetapi ketenangannya segera diganggu oleh tentara dan penduduk kota yang bergegas.</color>",
  ui_story_5054_50540202_1_dialog_content = "<color=#a8886f>Jeritan terputus-putus datang dari alun-alun. Beberapa pelarian yang beruntung memulai dengan kapal udara dalam upaya mereka untuk meninggalkan kota terapung yang konon paling aman.</color>",
  ui_story_5054_50540202_2_dialog_content = "<color=#a8886f>Sementara itu, di jalur yang hampir tidak terlihat, Anda melihat dua sosok yang sudah dikenal.</color>",
  ui_story_5054_50540202_3_dialog_content = "<color=#a8886f>Gadis berambut merah, Leona, dengan sepucuk surat di tangan, sedang berbicara dengan seseorang secara tidak terduga.</color>",
  ui_story_5054_50540202_4_dialog_content = "Berhenti!",
  ui_story_5054_50540202_5_dialog_content = "Apa?",
  ui_story_5054_50540202_6_dialog_content = "(Mereka saling kenal?)",
  ui_story_5054_50540202_7_dialog_content = "Apakah Anda menghasut Roshee untuk kabur dari rumah?",
  ui_story_5054_50540202_8_dialog_content = "Jika Anda menyinggung gadis yang sedang berbicara dengan saya, maka Anda salah orang.",
  ui_story_5054_50540202_9_dialog_content = "Dia mengira saya Kartima dan meminta saya untuk memberikan surat ini kepada Sharona Kartima.",
  ui_story_5054_50540202_10_dialog_content = "Berikan aku surat itu.",
  ui_story_5054_50540202_11_dialog_content = "Meskipun saya enggan membantunya, saya yakin saya tidak harus menjawab orang yang kasar.",
  ui_story_5054_50540202_12_dialog_content = "Aku tidak percaya ada seseorang di Lumopolis yang tidak mengenaliku, Otto Troy...",
  ui_story_5054_50540202_13_dialog_content = "<color=#a8886f>Suara mendesing!</color>",
  ui_story_5054_50540202_14_dialog_content = "<color=#a8886f>Sebelum Duke Troy selesai, gadis berambut merah itu membakar sudut surat itu.</color>",
  ui_story_5054_50540202_15_dialog_content = "Apa? Tangkap dia!",
  ui_story_5054_50540202_16_dialog_content = "<color=#a8886f>Surat yang terbakar melayang melewati mata Anda, dan sebelum terbakar, Anda melihat beberapa tulisan...</color>",
  ui_story_5054_50540202_17_dialog_content = "\"Insiden Eclipsite setahun yang lalu... Di balik layar... Duke Otto Troy... luar biasa... tidak bisa tinggal lebih lama lagi...\"",
  ui_story_5054_50540202_18_dialog_content = "<color=#a8886f>Mendesis...</color>",
  ui_story_5054_50540202_19_dialog_content = "<color=#a8886f>Surat itu berubah menjadi abu, menghilang dari jalan-jalan Lumopolis yang tidak ternoda, seperti masa lalu.</color>",
  ui_story_5054_50540203_1_dialog_content = "<color=#a8886f>Menabrak...</color>",
  ui_story_5054_50540203_2_dialog_content = "<color=#a8886f>Di halaman sebelah jalan, sebuah menara tiba-tiba runtuh. Debu menghujani sekitarnya dan menghalangi penglihatan.</color>",
  ui_story_5054_50540203_3_dialog_content = "Uhuk, uhuk...",
  ui_story_5054_50540203_4_dialog_content = "<color=#a8886f>Dari celah di antara puing-puing, batuk para lansia memecah kesunyian.</color>",
  ui_story_5054_50540203_5_dialog_content = "(Siapa itu di depannya?)",
  ui_story_5054_50540203_6_dialog_content = "Apakah kamu masih mengingatku?",
  ui_story_5054_50540203_7_dialog_content = "<color=#a8886f>Pria tua itu mendongak perlahan sebelum melihat ke tempat lain.</color>",
  ui_story_5054_50540203_8_dialog_content = "Apakah kamu tidak ingat Leona? Kalian ingin memecahkan telur naga di tanganku...",
  ui_story_5054_50540203_9_dialog_content = "Tidak, bukan kamu.",
  ui_story_5054_50540203_10_dialog_content = "<color=#a8886f>Gadis itu membeku seperti patung, terdiam untuk waktu yang lama...</color>",
  ui_story_5054_50540203_11_dialog_content = "Heh, terakhir kali saya mendengar sesuatu yang tidak masuk akal ini, saya baru berusia empat, lima tahun. Sekarang, saya tidak bisa diombang-ambingkan dengan mudah.",
  ui_story_5054_50540203_12_dialog_content = "Bahkan jika Anda terus mengoceh kepada saya bahwa \"Bukan kamu yang menyelamatkan Kartima\" seperti ibu saya yang Anda anggap gila ...",
  ui_story_5054_50540203_13_dialog_content = "Bukan kamu yang menyelamatkan Kartima... Begitu juga Mime...",
  ui_story_5054_50540203_14_dialog_content = "Dia akan segera menunjukkan dirinya! Dia datang!",
  ui_story_5054_50540203_15_dialog_content = "<color=#a8886f>Gadis berambut merah itu kembali terdiam, namun hanya sesaat, hingga ia tertawa terbahak-bahak penuh rasa iba dan duka yang menggema di pelataran kosong itu.</color>",
  ui_story_5054_50540203_16_dialog_content = "Ha ha ha! Ha ha ha-!",
  ui_story_5054_50540203_17_dialog_content = "Aku tahu seharusnya aku tidak kembali karena dipermalukan.",
  ui_story_5054_50540203_18_dialog_content = "<color=#a8886f>Anda meninggalkan kehancuran segera setelah Anda dapat melihat. Di antara puing-puing, seorang lansia menunggu penyelamat di benaknya.</color>",
  ui_story_5054_50540301_1_dialog_content = "<color=#a8886f>Suara ledakan, jeritan, jantung berdebar, dan senjata keras yang menusuk benda lunak meledak di sekitar ...</color>",
  ui_story_5054_50540301_2_dialog_content = "<color=#a8886f>Sayap raksasa menendang angin kencang satu demi satu, meniupkan debu ke wajah orang-orang yang melarikan diri dari tempat kejadian.</color>",
  ui_story_5054_50540301_3_dialog_content = "<color=#a8886f>Keringat, air mata, dan darah dengan cepat memenuhi aroma parfum yang dikenakan oleh seorang wanita bangsawan muda. Dia dan seorang bangsawan muda menyaksikan semuanya terungkap dalam ketakutan...</color>",
  ui_story_5054_50540301_4_option_content = "Ke sini, cepat!",
  ui_story_5054_50540301_5_dialog_content = "Terima kasih telah menunjukkan jalan keluar kepada kami! T-Tapi apa yang terjadi di sini?",
  ui_story_5054_50540301_6_dialog_content = "Pemberontakan! Pemberontakan terencana!",
  ui_story_5054_50540301_7_dialog_content = "Dewa Cahayaku... Mengapa ada orang yang melakukan itu di Lumopolis?",
  ui_story_5054_50540301_8_dialog_content = "Apakah Anda tidak ingat konsekuensi bagi mereka yang menentang aturan Schwartz, nona?",
  ui_story_5054_50540301_9_dialog_content = "House Pyrrhus baru-baru ini, lalu House Gautier, dan House Montague sebelumnya...",
  ui_story_5054_50540301_10_dialog_content = "Maksudmu rumah-rumah pengasingan?",
  ui_story_5054_50540301_11_dialog_content = "Astaga... Kudengar ada komplotan rahasia para penyintas yang merencanakan balas dendam mereka...",
  ui_story_5054_50540301_12_dialog_content = "Ini adalah kegilaan! Mereka semua sudah gila!",
  ui_story_5054_50540301_13_dialog_content = "Balas dendam hanyalah kepura-puraan bagi mereka yang berusaha untuk melengserkan! Dibutakan oleh dendam hanya akan membuatmu rentan terhadap manipulasi!",
  ui_story_5054_50540301_14_dialog_content = "(Komplotan rahasia? Melengserkan?)",
  ui_story_5054_50540301_15_dialog_content = "Sekarang bukan waktunya untuk memikirkannya. Kita harus lari!",
  ui_story_5054_50540301_16_dialog_content = "<color=#a8886f>Pasangan itu pergi sebelum Anda bisa menanyakan apa pun kepada mereka. Anda melihat ke arah mereka hanya untuk melihat mereka dikelilingi oleh pemberontak ...</color>",
  ui_story_5054_50540302_1_dialog_content = "<color=#a8886f>Anda sudah familiar dengan rute dari alun-alun kembali ke Schwartz Rumah besar. Anda juga tidak akan lupa bahwa pernah ada menara di jalan yang kini menjadi debu.</color>",
  ui_story_5054_50540302_2_dialog_content = "<color=#a8886f>Di antara bebatuan dan puing-puing terdengar suara serak dan bersemangat dari seorang lansia.</color>",
  ui_story_5054_50540302_3_dialog_content = "Anda! Itu kamu!",
  ui_story_5054_50540302_4_dialog_content = "(Siapa itu di depannya?)",
  ui_story_5054_50540302_5_dialog_content = "Anda akhirnya di sini untuk melihat saya!",
  ui_story_5054_50540302_6_dialog_content = "Saya Sharona Kartima. Anda tahu saya?",
  ui_story_5054_50540302_7_dialog_content = "Sharona, nama yang cantik... Ramalan memberi saya kemampuan untuk mengenali Anda, tetapi tidak akan mengungkapkan bahwa Anda memiliki nama yang begitu indah.",
  ui_story_5054_50540302_8_dialog_content = "Nubuat?",
  ui_story_5054_50540302_9_dialog_content = "<color=#a8886f>Orang tua mengamati sekeliling dengan hati-hati sebelum berbicara dengan suara rendah.</color>",
  ui_story_5054_50540302_10_dialog_content = "Di ruang bawah tanah rumah lama saya adalah pusaka Kartima, sebuah katana besar yang disebut Azure Api.",
  ui_story_5054_50540302_11_dialog_content = "Sekarang milikmu. Mengambil Azure Nyalakan dan selesaikan apa yang seharusnya Anda selesaikan!",
  ui_story_5054_50540302_12_dialog_content = "Azure Api? Saya melihat katana di ruang kerja Paman Mime dengan nama yang sama ...",
  ui_story_5054_50540302_13_dialog_content = "Beraninya penipu itu mengambil apa yang bukan miliknya!",
  ui_story_5054_50540302_14_dialog_content = "Tapi jangan khawatir, tidak peduli apakah dia menyimpannya Azure Api, itu milikmu!",
  ui_story_5054_50540302_15_dialog_content = "Hanya Anda yang dapat membuka kekuatannya!",
  ui_story_5054_50540302_16_dialog_content = "Pergi, anakku, cepat!",
  ui_story_5054_50540302_17_dialog_content = "<color=#a8886f>Sharon masih tersesat, tapi kau tahu itu dua belas tahun dari sekarang, Komandan Sharona dari Illumina akan memegang di tangannya sebuah pedang besar bernama Azure Api.</color>"
}
return config
